import java.util.Scanner;

public class Main {
    public static long computeGCD(long x, long y) {
        while (y != 0) {
            long temp = y;
            y = x % y;
            x = temp;
        }
        return x;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int a = sc.nextInt();
        int b = sc.nextInt();
        int n = sc.nextInt();

        int numerator = 0;
        int denominator = 1;
        double closest_diff = Double.POSITIVE_INFINITY;

        for (int j = 1; j <= n; ++j) {
            int lower_bound = (j * a) / b - 1;
            int upper_bound = (j * a) / b + 1;
            for (int i = lower_bound; i <= upper_bound; ++i) {
                double diff = Math.abs((double) i / j - (double) a / b);
                if (diff < closest_diff) {
                    closest_diff = diff;
                    numerator = i;
                    denominator = j;
                }
            }
        }
        long g = computeGCD(Math.abs(numerator), denominator);
        System.out.println((numerator / g) + "/" + (denominator / g));
        sc.close();
    }
}
